// src/modules/system/legal.js — văn bản pháp lý của AI Operations: Điều khoản dịch vụ, Chính sách bảo mật, Thanh toán &
// hoàn tiền, Quy định sử dụng, Phụ lục xử lý dữ liệu (DPA). Render bởi src/pages/system/legal/[slug].astro; footer
