/** Thứ tự = thứ tự trên mục lục, footer, sitemap. */
export const LEGAL_DOCS = [terms, privacy, refund, acceptableUse, dpa]

export const legalDoc = (slug) => LEGAL_DOCS.find((d) => d.slug === slug) ?? null
